"""Unitree H1 limited-mode spoon controller (rcb-limited/1.1)."""
import argparse
import json
import numpy as np
from rcb_client import Robot, EpisodeOver, ResetDenied


def normalized(angle, limits):
    lo, hi = limits
    return float(np.clip(2.0 * (angle - lo) / (hi - lo) - 1.0, -1.0, 1.0))


def action_from_obs(spec, obs):
    jpos = dict(zip(spec['proprio']['joints'], obs['proprio']['joint_pos']))
    names, ranges = spec['qpos']['layout'], spec['qpos']['range']
    a = np.zeros(len(names), dtype=np.float64)
    for i, name in enumerate(names[:16]):
        a[i] = normalized(jpos[name], ranges[i])
    for i in range(16, 21):
        a[i] = normalized(jpos[names[i]], ranges[i])
    for i, name in enumerate(names[21:], start=21):
        joint = name.replace('_A_', '_')
        if joint.endswith(('FFJ0', 'MFJ0', 'RFJ0', 'LFJ0')):
            base = joint[:-1]
            angle = jpos[base + '2'] + jpos[base + '1']
        else:
            angle = jpos[joint]
        a[i] = normalized(angle, ranges[i])
    return a


class Controller:
    def __init__(self):
        self.robot = Robot()
        self.spec = self.robot.spec()
        self.reset_refs(first=True)

    def reset_refs(self, first=False):
        self.obs = self.robot.observe(images=False) if first else self.robot.reset(images=False)
        self.command = action_from_obs(self.spec, self.obs)
        q = self.obs['proprio']['joint_pos']
        self.hip_base = 0.5 * (q[2] + q[7])
        self.roll_base = 0.5 * (q[1] + q[6])
        self.last_hip = self.hip_base
        self.last_roll = self.roll_base
        print('RESET', {'step': self.obs['step'], 'resets_left': self.obs['resets_left'],
                        'imu': self.obs.get('imu')}, flush=True)

    def reset(self):
        self.reset_refs(first=False)

    def segment(self, cfg):
        steps = max(1, int(cfg.get('steps', 100)))
        block = max(1, min(10, int(cfg.get('block', 5))))
        goal = self.command.copy()
        for idx, key in [(16, 'right_pitch'), (17, 'right_roll'),
                         (18, 'right_yaw'), (19, 'right_elbow'),
                         (20, 'right_wrist')]:
            if key in cfg:
                goal[idx] = normalized(float(cfg[key]), self.spec['qpos']['range'][idx])
        for idx, key in [(11, 'left_pitch'), (12, 'left_roll'), (13, 'left_yaw'),
                         (14, 'left_elbow'), (15, 'left_wrist')]:
            if key in cfg:
                goal[idx] = normalized(float(cfg[key]), self.spec['qpos']['range'][idx])
        for idx in (2, 7):
            if 'hip_pitch' in cfg:
                goal[idx] = normalized(float(cfg['hip_pitch']), self.spec['qpos']['range'][idx])
        for idx in (3, 8):
            if 'knee' in cfg:
                goal[idx] = normalized(float(cfg['knee']), self.spec['qpos']['range'][idx])
        for idx in (4, 9):
            if 'ankle' in cfg:
                goal[idx] = normalized(float(cfg['ankle']), self.spec['qpos']['range'][idx])
        if cfg.get('close'):
            goal[43:61] = 1.0
        if cfg.get('pinch'):
            goal[43:54] = 1.0
        if cfg.get('open'):
            # Use the starting observed finger posture for a relaxed, open hand.
            for i in range(43, 61):
                goal[i] = self.open_hand[i]

        start = self.command.copy()
        pos = 0
        done = False
        while pos < steps and not done:
            count = min(block, steps - pos)
            imu = self.obs.get('imu') or {}
            gx, gy = float(imu.get('gravity', [0, 0, -1])[0]), float(imu.get('gravity', [0, 0, -1])[1])
            wx, wy = float(imu.get('gyro', [0, 0, 0])[0]), float(imu.get('gyro', [0, 0, 0])[1])
            kp, kd = float(cfg.get('kp', 1.6)), float(cfg.get('kd', 0.08))
            rp, rd = float(cfg.get('kp_roll', 0.5)), float(cfg.get('kd_roll', 0.05))
            roll_sign = float(cfg.get('roll_sign', 1.0))
            want_hip = np.clip(self.hip_base + kp * gx + kd * wy,
                               self.hip_base - float(cfg.get('max_hip', 1.4)),
                               self.hip_base + float(cfg.get('max_hip', 1.4)))
            want_roll = np.clip(self.roll_base + roll_sign * (rp * gy - rd * wx),
                                self.roll_base - float(cfg.get('max_roll', 0.3)),
                                self.roll_base + float(cfg.get('max_roll', 0.3)))
            rate = float(cfg.get('balance_rate', 0.20))
            self.last_hip += float(np.clip(want_hip - self.last_hip, -rate, rate))
            self.last_roll += float(np.clip(want_roll - self.last_roll, -rate, rate))
            rows = []
            for k in range(count):
                u = min(1.0, (pos + k + 1) / steps)
                row = start + u * (goal - start)
                for idx in (2, 7):
                    row[idx] = normalized(self.last_hip, self.spec['qpos']['range'][idx])
                for idx in (1, 6):
                    row[idx] = normalized(self.last_roll, self.spec['qpos']['range'][idx])
                rows.append(row)
            ask = ['room_camera'] if pos + count >= steps else False
            try:
                self.obs = self.robot.step('qpos', np.asarray(rows), images=ask)
            except EpisodeOver as exc:
                print('EPISODE_OVER', str(exc), flush=True)
                return
            pos += int(self.obs.get('executed', count))
            done = bool(self.obs['done'])
            if pos % 25 < count or done:
                print('STEP', self.obs['step'], 'IMU', self.obs.get('imu'),
                      'DONE', done, self.obs.get('reason'), flush=True)
        self.command = goal
        if 'room_camera' in self.obs.get('images', {}):
            from PIL import Image
            Image.fromarray(self.obs['images']['room_camera']).save('/tmp/spoon_room.png')
        print('SEGMENT', {'step': self.obs['step'], 'done': self.obs['done'],
                          'reason': self.obs['reason'], 'resets_left': self.obs['resets_left'],
                          'imu': self.obs.get('imu')}, flush=True)
        print('STATUS', self.robot.status(), flush=True)

    def run_auto(self):
        # Stable stand, gradual reach, fingertip closure and lift; continue stirring in 40-step cycles.
        self.open_hand = self.command.copy()
        self.segment({'steps': 200, 'right_pitch': 0, 'right_elbow': 0,
                      'kp_roll': 0, 'kd_roll': 0})
        if self.obs['done']: return
        self.segment({'steps': 300, 'right_pitch': -0.7, 'right_elbow': 0.4,
                      'kp_roll': 0, 'kd_roll': 0})
        if self.obs['done']: return
        self.segment({'steps': 100, 'right_pitch': -0.5, 'right_elbow': 0.4,
                      'pinch': True})
        if self.obs['done']: return
        self.segment({'steps': 100, 'right_pitch': -0.2, 'right_elbow': 0.4})
        if self.obs['done']: return
        # Stir with a small 40-step cycle in shoulder pitch and elbow while maintaining the pinch.
        center_pitch, center_elbow = -0.2, 0.4
        for i in range(10):
            phase = 2.0 * np.pi * (i + 1) / 10.0
            self.segment({'steps': 40, 'right_pitch': center_pitch + 0.10*np.cos(phase),
                          'right_elbow': center_elbow + 0.10*np.sin(phase)})
            if self.obs['done']: return

    def interactive(self):
        self.open_hand = self.command.copy()
        print('READY: send one JSON object per line; keys include steps, right_pitch, right_roll, right_elbow, close, pinch, open, reset.', flush=True)
        for line in iter(input, ''):
            try:
                cfg = json.loads(line)
                if cfg.get('reset'):
                    self.reset()
                    self.open_hand = self.command.copy()
                else:
                    self.segment(cfg)
            except ResetDenied as exc:
                print('RESET_DENIED', str(exc), flush=True)
            except Exception as exc:
                print('ERROR', type(exc).__name__, str(exc), flush=True)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--interactive', action='store_true')
    parser.add_argument('--auto', action='store_true')
    args = parser.parse_args()
    c = Controller()
    c.open_hand = c.command.copy()
    if args.interactive:
        c.interactive()
    else:
        # Auto mode is the default so this file runs the complete recorded controller.
        while True:
            c.run_auto()
            if c.obs.get('done'):
                if c.obs.get('reason') == 'success':
                    break
                if int(c.obs.get('resets_left', 0)) <= 0:
                    break
                try:
                    c.reset()
                    c.open_hand = c.command.copy()
                except ResetDenied:
                    break
            elif c.obs.get('step', 0) < c.spec['max_episode_steps']:
                # Continue the remaining episode with the same stir cycle.
                c.segment({'steps': c.spec['max_episode_steps'] - c.obs['step'],
                           'right_pitch': -0.2, 'right_elbow': 0.4})
                if c.obs.get('done'):
                    if c.obs.get('reason') == 'success' or int(c.obs.get('resets_left', 0)) <= 0:
                        break
                    c.reset()
                    c.open_hand = c.command.copy()


if __name__ == '__main__':
    main()
